#!/usr/bin/env python3
"""Build the physical-boundary progress report from native evidence."""
from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1];r=root/'docs/reports/canyon-organic-boundary'
def read(name):
 p=r/name
 return p.read_text() if p.exists() else ''
def values(name,tag):
 m=re.search(tag+r' (.*)',read(name))
 return dict(re.findall(r'(\w+)=([^\s]+)',m.group(1))) if m else {}
checks={n:('PASS' if ('PASS' in read(n+'.log') or '100% tests passed' in read(n+'.log')) and 'FAIL' not in read(n+'.log') else 'pending / failed') for n in ['boundary-tests','geometry-tests','gameplay-tests','graphics-tests','occlusion-tests','boss-tests']}
remaining=['The repeated narrow cliff facets and room-wide terrace patterns remain unfinished. This is the playable-outline phase, not a claim of full visual reference fidelity.','Existing river-bank/channel influence regions retain their previous geometry; ordinary room boundaries are sculpted around them.','The established visual rock-height treatment remains separate from the taller canonical collision field.','Organic generation currently builds the classic layout once to preserve its roads, then rebuilds the boundary; this adds startup/floor-generation cost.','Only native Linux was validated; WASM checks remain waived.']
generation=values('boundary-tests.log','GENERATION');geometry=values('geometry-tests.log','GEOMETRY')
metrics={'base_commit':'b976baa','status':'Physical organic boundaries implemented; broader cliff art-direction work unfinished','checks':checks,'generation':generation,'geometry':geometry,'boundary_summary':read('boundary-tests.log').splitlines()[-1] if read('boundary-tests.log') else '', 'capture':{'zoom':160,'projection':'perspective','fov':45,'resolution':[1440,900],'base_seed':1866,'power_frames':120,'works_frames':60},'remaining':remaining}
(r/'measurements.json').write_text(json.dumps(metrics,indent=2)+'\n')
css='''*{box-sizing:border-box}body{margin:0;background:#1c2428;color:#eee2cb;font:17px/1.65 system-ui,sans-serif}main{max-width:1550px;margin:auto;padding:36px 24px}h1{font-size:clamp(32px,4vw,56px);line-height:1.1}h2{color:#dcb477;margin-top:40px}a{color:#8ad5b8}img{width:100%;height:auto;display:block}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0}figcaption{font-size:14px;color:#beb5a6;padding:9px 0}.note{background:#303027;border-left:4px solid #d4a467;padding:18px}p,li{max-width:1100px}code,pre{background:#2a353b;border-radius:5px}code{padding:3px 5px}pre{padding:18px;overflow:auto}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:12px;border-bottom:1px solid #45525a}.scroll{overflow:auto}@media(max-width:700px){.pair{grid-template-columns:1fr}main{padding:20px 14px}}'''
h='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard · Organic playable canyon boundary</title><style>'''+css+'''</style><main><p class="notice">Historical outline-only phase. The <a href="../canyon-formations/index.html">current contour and terrace correction</a> includes the later boundary collar, wall topology changes and current validation.</p><p>DeathWard · Physical canyon boundary phase</p><h1>The playable outline<br>now changes with the rock.</h1><p class="note"><b>The user authorized changing the actual playable boundary.</b> This pass changes collision and navigation around seeded lobes and concave bays. Roads, exit sockets and the room graph are preserved. Narrow cliff facets and continuous terrace bands are still visible; their art-direction correction remains unfinished.</p><h2>Actual traversable outline</h2><p>Sampled collision at 0.5-metre spacing in the same seeded Works room. Dark areas are solid ground or existing boulders. Pink circles are unchanged passage sockets; the dashed line is the previous outline. This plot is generated from collision samples, not painted over a screenshot. The earlier physical boundary already contained curved regions; the new profile adds stronger asymmetry and bays.</p><a href="floor-outlines.png"><img src="floor-outlines.png" alt="Classic and organic actual playable outlines"></a><p><a href="floor-grid.csv">Collision samples</a> · <a href="road.csv">Preserved road samples</a> · <a href="sockets.csv">Sockets</a></p><h2>Matched native captures</h2><p>Same executable, seed, room and unchanged 160% camera / 45° perspective / 1440 × 900. Classic mode restores the old physical outline for comparison. Screenshots are unretouched. The quiet power room avoids enemy attack effects obscuring the terrain.</p>'''
for name,title in [('power','Quiet room'),('works','Works room, with ordinary combat residents')]:
 h+=f'<h3>{title}</h3><div class="pair"><figure><a href="classic-{name}.png"><img src="classic-{name}.png" alt="Classic boundary native capture"></a><figcaption>Classic playable boundary · <a href="classic-{name}.log">Log</a></figcaption></figure><figure><a href="organic-{name}.png"><img src="organic-{name}.png" alt="Organic boundary native capture"></a><figcaption>Organic playable boundary · <a href="organic-{name}.log">Log</a></figcaption></figure></div>'
h+='''<h2>Implementation</h2><ul><li><code>CanyonBoundaryStyle</code> selects Classic or Organic construction. Organic is the default. The public <code>buildCanyon()</code> entry point remains compatible.</li><li>The ordinary basin profile uses correlated angular components at two, three and five lobes. A bounded smooth function produces broader protrusions and deeper concave bays without consuming the existing layout/outcrop RNG stream.</li><li>The established layout is first generated in Classic mode to obtain its exact seeded road. Organic generation reserves that road and its shoulders, plus the existing center/objective/arrival/socket corridors and space around retained outcrops.</li><li>Original river courses, bank influence areas and repaired fords are reused. Boundary-river bank rooms keep their existing shore openings. This prevents boundary sculpting from isolating banks or inventing new crossings.</li><li>A bounded navigation flood removes only tiny disconnected edge pockets, protecting anchors, roads and water crossings. Floor cells, room floor area and collision are then rebuilt from the final terrain.</li><li>Road planning retains an already generated road rather than recomputing a different path on the reshaped floor. Clearing its samples explicitly requests replanning.</li><li>Sharper concave boundaries exposed folds in the existing cosmetic rim deformation. An orientation guard reduces that deformation coherently across the mesh until it preserves winding. Visual ray normals now handle very small clipped triangles correctly; regressions cover both failures.</li></ul><p>The room graph, room IDs, centers, bounds, objective/entry/exit anchors and passage transforms are unchanged. The floor inside those envelopes is intentionally different. Actual usable area can change, and existing area-based enemy placement/budget rules consume that area as before. No AI, combat, controls, UI, camera, material or lighting code was edited. No assets or vegetation-density settings were changed; terrain-aware dressing naturally resamples support against the new terrain.</p><h2>Native validation</h2><div class="scroll"><table><tr><th>Suite</th><th>Status</th><th>Evidence</th></tr>'''
for n,status in checks.items():h+=f'<tr><td>{n}</td><td>{status}</td><td><a href="{n}.log">Log</a></td></tr>'
h+='''</table></div><p>The boundary suite compares independently generated Classic and Organic maps, repeats seeds, checks exact road positions/widths/rut coordinates, unchanged river centerlines/widths, unchanged room and passage identities, clear cores/sockets, changed physical floor signs and three five-room tutorial maps. Existing suites exercise road shoulders, both river types, ford connectivity, combat seals, variable 9–15-room floors, keys, room graphs and boss clearance. GPU suites check actual visible mesh rays, supported props, density stability, fading, outlines and real firing input. Boss tests cover early and late floor profiles with weak builds.</p><pre>'''+metrics['boundary_summary']+'</pre><pre>'+json.dumps(geometry,indent=2)+'''</pre><h2>Generation cost</h2><p>Fourteen matched Classic/Organic construction samples in the native boundary test, without rendering. Seed-replay constructions are excluded from the paired timings. This is a local startup observation, not a gameplay FPS benchmark. Organic currently performs two construction passes to preserve the existing road course.</p><pre>'''+json.dumps(generation,indent=2)+'''</pre><h2>Reversibility and usage</h2><pre># New physical boundaries (default)
./build/deathward --expedition --theme canyon --style original

# Previous physical boundaries, same visual treatment
DEATHWARD_CANYON_BOUNDARY=classic ./build/deathward --expedition --theme canyon --style original</pre><p><code>DEATHWARD_CANYON_BOUNDARY=organic</code> explicitly selects the new mode. Unknown values fail clearly. The older <code>assets/visual/canyon.cfg</code> enabled flag still controls appearance; the boundary mode controls the actual floor/collision generator. Restart or generate a new expedition to compare modes.</p><h2>Remaining work</h2><ul>'''
for item in remaining:h+='<li>'+item+'</li>'
h+='''</ul><p>This completes the physical-boundary phase, not the full reference-matching task. The next visual work must address cliff facet topology and local terrace placement without replacing the canyon with the rejected low rim and flat masses.</p><p>Changed sources: <code>CanyonTerrain.cpp</code>, <code>CanyonBoundary.hpp</code>, <code>CanyonRoad.cpp</code>, the mesh-safety fixes in <code>CanyonAppearance.cpp</code>, focused tests and CMake registration. The annotated specification remains below for future acceptance.</p><a href="specification.png"><img loading="lazy" src="specification.png" alt="User annotated visual acceptance reference"></a><p><a href="measurements.json">Structured status</a> · <a href="native-build.log">Build evidence</a></p></main></html>'''
(r/'index.html').write_text(h)
print(json.dumps(checks,indent=2))
